import{_ as t,C as a,o as i,c as r,ag as o,E as n}from"./chunks/framework.yGqRar0R.js";const k=JSON.parse('{"title":"Installing Protocube","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installing-protocube.md","filePath":"guide/installing-protocube.md"}'),l={name:"guide/installing-protocube.md"};function c(d,e,p,h,u,b){const s=a("ComposeDownloads");return i(),r("div",null,[e[0]||(e[0]=o('<h1 id="installing-protocube" tabindex="-1">Installing Protocube <a class="header-anchor" href="#installing-protocube" aria-label="Permalink to &quot;Installing Protocube&quot;">​</a></h1><p><strong>Protocube</strong> is the SLS control plane it tracks instances and coordinates <strong>nodes</strong> (daemons). Install it once before you add nodes. For shared prerequisites (Linux, WSL, Docker), read <a href="./getting-started.html">Getting started</a> first.</p><p>Official image: <code>ghcr.io/jessefaler/sls/protocube:latest</code><br> Binaries and release notes: <a href="https://github.com/jessefaler/SLS/releases" target="_blank" rel="noreferrer">SLS GitHub Releases</a>.</p><h2 id="docker-compose-file" tabindex="-1">Docker Compose file <a class="header-anchor" href="#docker-compose-file" aria-label="Permalink to &quot;Docker Compose file&quot;">​</a></h2><p>Download the official compose definition or open it on GitHub: <a href="https://github.com/jessefaler/SLS/blob/main/protocube/docker-compose.yml" target="_blank" rel="noreferrer"><code>protocube/docker-compose.yml</code></a>.</p>',5)),n(s,{which:"protocube"}),e[1]||(e[1]=o(`<h2 id="run-protocube-with-docker-recommended" tabindex="-1">Run Protocube with Docker (recommended) <a class="header-anchor" href="#run-protocube-with-docker-recommended" aria-label="Permalink to &quot;Run Protocube with Docker (recommended)&quot;">​</a></h2><ol><li><p>Save the Compose file as <code>docker-compose.yml</code> in an empty directory (download it above or copy it from GitHub).</p></li><li><p>Start the stack:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div></li></ol><p>By default, Protocube listens on port <code>5620</code>, which is mapped to the host in the Compose file.</p><p>The Compose configuration also sets <code>extra_hosts</code> so hostnames like <code>protocube.sls.net</code> and <code>daemon.sls.net</code> resolve <strong>inside containers</strong>. If you need to use these hostnames from the <strong>host system</strong> or from native binaries, you may need to add matching entries to your <code>/etc/hosts</code> file.</p><p>On first start Protocube will create a default config under <strong><code>/etc/sls/protocube/</code></strong>. Continue with <a href="#configuring-protocube">Configuring Protocube</a>.</p><h2 id="run-protocube-from-a-release-binary" tabindex="-1">Run Protocube from a release binary <a class="header-anchor" href="#run-protocube-from-a-release-binary" aria-label="Permalink to &quot;Run Protocube from a release binary&quot;">​</a></h2><ol><li><p>Open <a href="https://github.com/jessefaler/SLS/releases" target="_blank" rel="noreferrer">SLS Releases</a> and download the <strong>protocube</strong> asset for your OS and CPU architecture.</p></li><li><p>Install it on your <code>PATH</code> or run it from a fixed location:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protocube</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sls/protocube</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/sls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/sls/protocube</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/sls/protocube</span></span></code></pre></div></li><li><p>Start Protocube:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-S3Qu7" id="tab-_77bi6S" checked><label data-title="First run" for="tab-_77bi6S">First run</label><input type="radio" name="group-S3Qu7" id="tab-FZshtVG"><label data-title="Custom config" for="tab-FZshtVG">Custom config</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./protocube</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./protocube</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sls/protocube/config.yml</span></span></code></pre></div></div></div></li></ol><p>If no config exists yet the process will create a default config at <strong><code>/etc/sls/protocube/</code></strong></p><h2 id="configuring-protocube" tabindex="-1">Configuring Protocube <a class="header-anchor" href="#configuring-protocube" aria-label="Permalink to &quot;Configuring Protocube&quot;">​</a></h2><p>Protocube reads <strong><code>/etc/sls/protocube/config.yml</code></strong> by default (or the path you pass with <code>--config</code>). There you set blueprint and software roots, API listen address, TLS, and related options. See <a href="/sls-docs/reference/configuration.html">Configuration</a> as that reference page grows.</p><p>When Protocube is running, continue with <a href="./installing-daemon.html">Installing the daemon</a> on each host that should run game servers.</p><h2 id="protocube-cli-and-api-keys" tabindex="-1">Protocube CLI and API Keys <a class="header-anchor" href="#protocube-cli-and-api-keys" aria-label="Permalink to &quot;Protocube CLI and API Keys&quot;">​</a></h2><p>For Protocube CLI commands and instructions on creating API keys, see <a href="/sls-docs/reference/cli.html">CLI Reference</a>.</p>`,13))])}const m=t(l,[["render",c]]);export{k as __pageData,m as default};
